import json, os, glob, shutil
root = "/j-jepa-vol/phatjet-sonn/runs"
kept = 0
for d in sorted(glob.glob(root + "/*/")):
    m = os.path.join(d, "metrics.json")
    if not os.path.exists(m):
        continue
    try:
        n = json.load(open(m)).get("epochs_completed", 0)
    except Exception:
        continue
    snap = os.path.join(d, "metrics.snapshot.json")
    prev = 0
    if os.path.exists(snap):
        try:
            prev = json.load(open(snap)).get("epochs_completed", 0)
        except Exception:
            prev = 0
    if n > prev:
        shutil.copy2(m, snap)
        kept += 1
print(f"updated {kept} snapshots")

